function ago(ms){ if(!ms) return '?';
  var s=Math.max(0,(Date.now()-ms)/1000);
  if(s<90) return Math.round(s)+' sec ago';
  var m=s/60; if(m<90) return Math.round(m)+' min ago';
  var h=m/60; if(h<48) return Math.round(h)+' hr ago';
  return Math.round(h/24)+' d ago'; }
function cap(x){ x=String(x||''); return x.charAt(0).toUpperCase()+x.slice(1); }
// mqtt-in "auto-detect" hands us a parsed object for JSON topics, a string
// for plain ones, or a Buffer. Normalise to an object here.
function obj(p){
  if(p && typeof p==='object' && typeof p.length==='undefined') return p; // already parsed
  try { return JSON.parse(typeof p==='string' ? p : p.toString()); } catch(e){ return null; }
}
var t=msg.topic, o=null;
try{
  if(t==='stat/powerstrip1/POWER5'){
    var v=(msg.payload && typeof msg.payload==='object')
            ? (msg.payload.POWER5 || msg.payload.POWER || JSON.stringify(msg.payload))
            : String(msg.payload);
    o={topic:'aether/Antenna', payload:String(v), retain:true};
  } else if(t==='lightning/as3935/last_event'){
    var d=obj(msg.payload); if(!d) return null;
    // Stash event + timestamp; the timer function recomputes "N min ago" live.
    var l={event:d.event, ts:d.ts_epoch_ms};
    flow.set('lastLightning', l);
    o={topic:'aether/Lightning', payload:cap(l.event)+', '+ago(l.ts), retain:true};
  } else if(t==='lightning/as3935/status'){
    var d=obj(msg.payload); if(!d) return null;
    o={topic:'aether/AS3935', payload:(d.event==='offline'?'Offline':'Active'), retain:true};
  } else if(t==='shack/gpsntp/chrony'){
    var d=obj(msg.payload); if(!d) return null;
    var off=d.last_offset_s||0, ns=off*1e9, os;
    if(Math.abs(ns)<1000) os=(ns>=0?'+':'')+Math.round(ns)+' ns';
    else if(Math.abs(ns)<1e6) os=(ns>=0?'+':'')+(ns/1000).toFixed(1)+' us';
    else os=(off>=0?'+':'')+(off*1000).toFixed(2)+' ms';
    o={topic:'aether/GPS', payload:'S'+(d.stratum!=null?d.stratum:'?')+' '+os, retain:true};
  }
}catch(e){}
return o;

function ago(ms){ if(!ms) return '?';
  var s=Math.max(0,(Date.now()-ms)/1000);
  if(s<90) return Math.round(s)+' sec ago';
  var m=s/60; if(m<90) return Math.round(m)+' min ago';
  var h=m/60; if(h<48) return Math.round(h)+' hr ago';
  return Math.round(h/24)+' d ago'; }
function cap(x){ x=String(x||''); return x.charAt(0).toUpperCase()+x.slice(1); }
var out=[];
// LP-700 power/SWR from global (mirrored by LP State Aggregator)
var s=global.get('lpState');
if(s){
  var p=(s.avg!=null?s.avg:(s.peak!=null?s.peak:null));
  var swr=(s.swr!=null?s.swr:null);
  if(p!=null)   out.push({topic:'aether/Power', payload:String(p)+' W', retain:true});
  if(swr!=null) out.push({topic:'aether/SWR',   payload:parseFloat(swr).toFixed(2)+':1', retain:true});
}
// Lightning "N min ago" recomputed live from the stashed last event
var l=flow.get('lastLightning');
if(l && l.ts){
  out.push({topic:'aether/Lightning', payload:cap(l.event)+', '+ago(l.ts), retain:true});
}
// Single output → wrap the array so ALL messages are sent (not just out[0]).
return [ out ];
